## suitability_functions.R - split out of functions.R.
## Do not edit this header; it is regenerated by the split script.

#' Area of applicability surfaces, keeping every intermediate CAST produces
#'
#' @description Computes \code{CAST::trainDI()} once for the model and saves it (training
#' dissimilarities, the AOA threshold, variable weights, and training LPD) as
#' \code{results_root/modelsTune/{fname}-trainDI.rds}, then predicts
#' \code{CAST::aoa()} over the raster stack block-wise with that trainDI - rather than
#' letting aoa() recompute it for every block - and writes all three surfaces as layers of
#' \code{results_root/suitability_maps/{fname}-AOA-surfaces.tif}: \code{DI} (dissimilarity
#' index), \code{AOA} (1 inside / 0 outside), and, with \code{LPD = TRUE}, \code{LPD}
#' (local point density: how many training points are within the DI threshold of each
#' pixel). The binary layer is also written on its own to \code{{fname}-AOA.tif}, the
#' single-layer file downstream scripts already read. Earlier versions kept only that
#' binary layer. Callable on its own to (re)build the surfaces for an already-fitted model
#' without refitting it.
#' @param model The caret \code{train} object (\code{results_root/modelsTune/{fname}.rds}).
#' @param rast_dat SpatRaster of predictors the model was fit on.
#' @param fname Model file stem.
#' @param results_root Results tree to write into.
#' @param LPD Logical. Also compute local point density; noticeably slower, especially at
#' 1/3 arc-second. Default TRUE so nothing is left to recompute later.
#' @param overwrite Logical. Recompute and overwrite an existing AOA raster/trainDI.
#' @return The trainDI object, invisibly.
aoaSurfaces <- function(model, rast_dat, fname, results_root, LPD = TRUE, overwrite = TRUE){

  tdi_path <- file.path(results_root, 'modelsTune', paste0(fname, '-trainDI.rds'))
  if(file.exists(tdi_path) && !overwrite){
    tdi <- readRDS(tdi_path)
  } else {
    message('Computing trainDI (once) for ', fname)
    tdi <- CAST::trainDI(model, LPD = LPD, verbose = FALSE)
    saveRDS(tdi, tdi_path)
  }

  layers <- c('DI', 'AOA', if(LPD) 'LPD')
  AOAfun <- function(model, r, tdi, LPD, layers){
    a <- CAST::aoa(r, model, trainDI = tdi, LPD = LPD, verbose = FALSE)
    as.data.frame(a[layers])
  }

  pout <- file.path(results_root, 'suitability_maps')
  surf_path <- file.path(pout, paste0(fname, '-AOA-surfaces.tif'))
  # Honour overwrite = FALSE for the surfaces too (not just the trainDI read above): skip the
  # expensive predict/write when they already exist rather than letting terra error on them.
  if(file.exists(surf_path) && !overwrite){
    message('AOA surfaces already exist; skipping (overwrite = FALSE): ', surf_path)
    return(invisible(tdi))
  }
  message('Writing Area of Applicability surfaces (', paste(layers, collapse = ', '), ') to raster')
  surf <- terra::predict(
    rast_dat, model = model, fun = AOAfun, tdi = tdi, LPD = LPD, layers = layers,
    cores = 1, cpkgs = 'CAST', na.rm = TRUE,
    filename = surf_path,
    wopt = list(names = layers), overwrite = overwrite)
  # the single-layer binary AOA raster every downstream script reads (threshold masks,
  # patches, cost distances, maps) - unchanged in name and content
  terra::writeRaster(surf[['AOA']], file.path(pout, paste0(fname, '-AOA.tif')),
                     names = 'AOA', overwrite = overwrite)

  invisible(tdi)
}


#' Inverse env-density case weights for presences
#'
#' @description Reweights presences so clusters in environmental space do not dominate
#' the fit. PCA on the full numeric predictor stack of the training frame, 1-NN KDE on
#' the first \code{n_pcs} PCs (ks::Hpi bandwidth, Scott's rule fallback), weight =
#' \code{(1 / density)^alpha}, capped at the \code{cap_q} quantile, rescaled so
#' mean(weight) = 1 across presences. Absences keep weight 1. The alpha exponent softens
#' the raw inverse density (alpha = 1) toward uniform (alpha = 0); the capped quantile
#' limits a single sparse-env presence from eating the fit. Lower \code{n_pcs} reduces
#' the dimensionality the KDE has to cover - with a few hundred presences, 5-D is sparse
#' enough that Hpi lands on a very spiky density and the cap does not bite. Compute on
#' the training frame only; call per fold, after any Boruta pruning.
#' @param Train data.frame with factor \code{Occurrence} (levels '0','1') + numeric predictors.
#' @param n_pcs Integer, number of principal-component axes for the density estimate.
#' @param alpha Numeric in [0, 1], softening exponent on the inverse density.
#' @param cap_q Numeric in (0, 1), upper-quantile cap on the inverse-density weight.
#' @return Numeric vector of length nrow(Train), aligned to Train row order.
envPCWeights <- function(Train, n_pcs = 3, alpha = 0.5, cap_q = 0.80){
  stopifnot('Occurrence' %in% names(Train))
  X <- Train[, setdiff(names(Train), 'Occurrence'), drop = FALSE]
  X <- X[, vapply(X, is.numeric, logical(1)), drop = FALSE]
  pres <- as.character(Train$Occurrence) == '1'
  if(sum(pres) < max(n_pcs + 2, 10) || ncol(X) < 2){
    warning('envPCWeights(): too few presences or predictors; equal weights.', immediate. = TRUE)
    return(rep(1, nrow(Train)))
  }
  pc <- stats::prcomp(X[pres, , drop = FALSE], center = TRUE, scale. = TRUE)
  k  <- min(n_pcs, ncol(pc$x))
  Z  <- pc$x[, seq_len(k), drop = FALSE]
  H  <- tryCatch(ks::Hpi(Z, nstage = 2), error = function(e) NULL)
  if(is.null(H)) H <- diag(apply(Z, 2, stats::bw.nrd0)^2, nrow = k, ncol = k)
  fhat <- ks::kde(Z, H = H, eval.points = Z)$estimate
  fhat <- pmax(fhat, max(fhat) * 1e-6)
  w_pres <- (1 / fhat)^alpha
  w_pres <- pmin(w_pres, stats::quantile(w_pres, cap_q))
  w_pres <- w_pres / mean(w_pres)
  message(sprintf('envPCWeights: k=%d alpha=%.2f cap_q=%.2f  w summary: min=%.2f median=%.2f mean=%.2f max=%.2f',
                  k, alpha, cap_q, min(w_pres), stats::median(w_pres), mean(w_pres), max(w_pres)))
  w <- rep(1, nrow(Train))
  w[pres] <- w_pres
  w
}

#' Mahalanobis env-distance case weights for presences
#'
#' @description Weights each presence by its (regularized) Mahalanobis distance to the
#' training-presence centroid in the raw covariate space - presences far from the
#' centroid in env space get up-weighted. Different hypothesis than
#' \code{envPCWeights()}: "weight env-marginal relative to the centroid" rather than
#' "weight sparse neighborhoods", and uses every covariate rather than the top k PCs.
#' Weight = Mahalanobis_dist^(2 * alpha), capped at the \code{cap_q} quantile and
#' rescaled so mean(weight) = 1 across presences. Absences keep weight 1.
#' @param Train data.frame with factor \code{Occurrence} (levels '0','1') + numeric predictors.
#' @param alpha Numeric in [0, 1], softening exponent on the raw squared distance.
#' @param cap_q Numeric in (0, 1), upper-quantile cap on the weight.
#' @return Numeric vector of length nrow(Train), aligned to Train row order.
envMahalanobisWeights <- function(Train, alpha = 0.5, cap_q = 0.80){
  stopifnot('Occurrence' %in% names(Train))
  pres <- as.character(Train$Occurrence) == '1'
  X <- Train[, setdiff(names(Train), 'Occurrence'), drop = FALSE]
  X <- X[, vapply(X, is.numeric, logical(1)), drop = FALSE]
  if(sum(pres) < max(ncol(X) + 2, 10) || ncol(X) < 2){
    warning('envMahalanobisWeights(): too few presences or predictors; equal weights.',
            immediate. = TRUE)
    return(rep(1, nrow(Train)))
  }
  Xp <- as.matrix(X[pres, , drop = FALSE])
  mu <- colMeans(Xp)
  S  <- stats::cov(Xp)
  # ridge-regularize if the presence covariance is singular (near-collinear covariates)
  if(any(is.na(S)) || qr(S)$rank < ncol(Xp)){
    S <- S + diag(1e-6 * mean(diag(S)) + 1e-9, ncol(Xp))
  }
  d2 <- stats::mahalanobis(Xp, center = mu, cov = S)
  w_pres <- pmax(d2, 1e-9)^alpha  # d2 is already squared distance; alpha = 0.5 -> raw dist
  w_pres <- pmin(w_pres, stats::quantile(w_pres, cap_q))
  w_pres <- w_pres / mean(w_pres)
  message(sprintf('envMahalanobisWeights: p=%d alpha=%.2f cap_q=%.2f  w summary: min=%.2f median=%.2f mean=%.2f max=%.2f',
                  ncol(Xp), alpha, cap_q, min(w_pres), stats::median(w_pres), mean(w_pres), max(w_pres)))
  w <- rep(1, nrow(Train))
  w[pres] <- w_pres
  w
}

#' Platt recalibration: logistic fit of truth on logit(prob)
#'
#' @description Learns a two-parameter sigmoid \code{sigmoid(a + b * logit(p))} that
#' maps model probabilities to the empirical presence rate on an unweighted holdout.
#' Use after a case-weighted fit, where the raw predicted P scale no longer reflects
#' the landscape presence base rate.
#' @param truth Numeric or factor coding 0/1 on the calibration fold.
#' @param prob Numeric, raw model probability of presence for the same rows.
#' @return List with \code{coef} (intercept, slope) and \code{apply}, function(p) -> p_cal.
plattCalibrate <- function(truth, prob){
  y <- as.integer(as.character(truth))
  p <- pmin(pmax(prob, 1e-6), 1 - 1e-6)
  fit <- stats::glm(y ~ stats::qlogis(p), family = stats::binomial())
  cf  <- stats::setNames(stats::coef(fit), c('intercept', 'slope'))
  apply_fn <- function(p){
    p <- pmin(pmax(p, 1e-6), 1 - 1e-6)
    stats::plogis(cf['intercept'] + cf['slope'] * stats::qlogis(p))
  }
  list(coef = cf, apply = apply_fn)
}


#' @param x input occurrence data
#' @param resolution list of paths to geodata at different resolutions.
#' @param iteration numeric, which iteration of modelling is being performed?
#' @param se_prediction boolean, whether to predict the SE surfaces or not; cost can be
#' substantial at fine resolutions.
#' @param p2proc path to the processed raster data. 
#' @param train_split Numeric. The proportion of data to use for train, at first iteration
#' a standard 0.8, good, but lot's of data are available for test later so up to 0.9 good.
#' @param PAratio Numeric. The ratio of presence to absences - simply for appending to file name, 
#' the exact quantity are saved in model objects. "1:2" 
#' @param distOrder Character. The distance between the nearest absence to presence, as a multiple of the cell resolution
#' e.g. distOrder 1 at a 90m resolution indicates the nearest absence is >90m away from a presence, at 10m it indicates > 10m away.
#' @param seed Numeric. Passed to \code{set.seed()} before the train/test split and
#' model fit, so replicate calls at the same PAratio/resolution can use independent
#' seeds instead of silently reusing whichever model was fit first.
#' @param predict_surface Boolean. Defaults to TRUE. When FALSE, skip the probability
#' surface, area-of-applicability, and standard-error raster predictions entirely -
#' fitting and holdout evaluation still happen, and are fast, so this is what a grid/
#' replicate search over PAratio should use; only the final, chosen model needs the
#' (slow) full-surface predictions.
#' @param results_root Character, a directory with models/modelsTune/tables/test_data/
#' evaluations/suitability_maps subfolders, written and read exactly like
#' \code{PROJ_ROOT}'s own \code{results/} tree. Defaults to that tree; override to run a
#' parallel comparison (e.g. a different train/test split strategy) without reading or
#' overwriting anything under the default results.
modeller <- function(x, resolution, iteration, se_prediction, p2proc, train_split,
                     PAratio, distOrder, seed = 1, predict_surface = TRUE,
                     split = NULL, part = NULL, weight_scheme = 'W0',
                     results_root = file.path(PROJ_ROOT, 'results')){
  weight_scheme <- match.arg(weight_scheme, c('W0', 'WKDE', 'WMAH'))

  if(missing(se_prediction)){se_prediction <- FALSE}
  set.seed(seed)
  rast_dat <- rastReader(paste0('dem_', resolution), p2proc)
  cores <- parallel::detectCores()

  # When `part` is supplied, it is authoritative for BOTH the outer train/test split and
  # the inner CV folds; any `split` argument is ignored. The caller must have attached
  # `abs_k` (stable row id in the absence pool at partition-build time) to absence rows of
  # `x` and left `.id` on both classes - the join keys for mapping partition rows (pid =
  # pres_<.id> / abs_<abs_k>) onto Train rows.
  if(!is.null(part) && !is.null(split))
    stop('modeller(): pass `part` or `split`, not both.')
  use_part <- !is.null(part)
  if(use_part && !'abs_k' %in% names(x))
    stop("modeller(): `part` supplied but `x` has no `abs_k` column on absences.")

  df <- dplyr::bind_cols(
    dplyr::select(x, Occurrence, dplyr::any_of(c('.id', 'abs_k'))),
    dplyr::select(terra::extract(rast_dat, x), -ID),
  ) |>
    # drop rows with NA predictors - .id/abs_k are id columns and must not trigger the drop
    # (abs_k is NA on presences by construction)
    tidyr::drop_na(-dplyr::any_of(c('.id', 'abs_k'))) %>%
    dplyr::mutate(
      Occurrence = as.factor(Occurrence)) |>
    sf::st_drop_geometry()

  fname <- fname_build(resolution, iteration, PAratio, distOrder, seed, weight_scheme)
  #######################         MODELLING           ##########################
  # Random Forest with default settings - this paper isn't comparing model
  # families, and RF defaults absorb a lot of the stochasticity that would
  # otherwise show up as hyperparameter sensitivity.
  
  # only rerun modelling if a saved .rds object doesn't exist. Reload both objects: the
  # cross-validated caret `model` for CAST::aoa()'s weighting/CV folds - not just `rf_model`.
  if(file.exists(paste0(results_root, '/models/', fname, '.rds'))){
    rf_model <- readRDS(paste0(results_root, '/models/', fname, '.rds'))
    model <- readRDS(paste0(results_root, '/modelsTune/', fname, '.rds'))
    platt_path <- paste0(results_root, '/modelsTune/', fname, '-platt.rds')
    platt <- if(file.exists(platt_path)) readRDS(platt_path) else NULL
    platt_apply <- if(is.null(platt)) function(p) p else platt$apply
    message(
      'An existing model for this resolution and iteration already exists;
      reloading it now for prediction')
  } else {
  
  # split the input data into both an explicit train and test data set. Three paths:
  # (a) `part` from Partitioner.R  - authoritative for outer split AND inner CV folds;
  # (b) pre-computed spatial split (spatial_class_split()) - every ratio/seed in a
  #     resolution's grid search shares the same class-balanced, prediction-domain-
  #     matched partition and modeller() derives its own inner knndm folds;
  # (c) null - fall back to a random stratified split, inner knndm folds as (b).
  partition_cv <- NULL                       # populated under (a); drives trainControl
  if(use_part){
    df$pid <- ifelse(df$Occurrence == '1',
                     paste0('pres_', df$.id),
                     paste0('abs_',  df$abs_k))
    train_pid <- part$combined$id[part$combined$set == 'train']
    test_pid  <- part$combined$id[part$combined$set == 'test']
    Train <- df[df$pid %in% train_pid, , drop = FALSE]
    Test  <- df[df$pid %in% test_pid,  , drop = FALSE]
    # remap partition fold indices (positional into part$train_frame) onto Train rows,
    # dropping any train_frame rows that aren't in this ratio's absence subsample
    tf <- part$combined[part$combined$set == 'train', , drop = FALSE]
    train_row <- setNames(seq_len(nrow(Train)), Train$pid)
    remap <- function(idx_list) lapply(idx_list, function(i){
      r <- train_row[tf$id[i]]; unname(r[!is.na(r)])
    })
    partition_cv <- list(indx_train   = remap(part$indx_train),
                         indx_test    = remap(part$indx_test),
                         indx_exclude = remap(part$indx_exclude))
  } else if(is.null(split)){
    TrainIndex <- caret::createDataPartition(
      df$Occurrence, p = train_split, list = FALSE, times = 1)
    Train <- df[TrainIndex,]; Test <- df[-TrainIndex,]
  } else {
    Train <- df[df$.id %in% split$train_id, ]
    Test  <- df[df$.id %in% split$test_id, ]
  }
  Train <- dplyr::select(Train, -dplyr::any_of(c('.id', 'abs_k', 'pid')))
  Test  <- dplyr::select(Test,  -dplyr::any_of(c('.id', 'abs_k', 'pid')))

  # WKDE: carve a stratified 15% unweighted calibration fold out of Train for the Platt
  # fit. The final model is trained on the remaining 85% (with weights). W0 skips this.
  Cal <- NULL
  if(weight_scheme %in% c('WKDE', 'WMAH')){
    cal_idx <- as.integer(caret::createDataPartition(Train$Occurrence, p = 0.15,
                                                     list = FALSE, times = 1))
    Cal   <- Train[cal_idx, , drop = FALSE]
    Train <- Train[-cal_idx, , drop = FALSE]
    if(!is.null(partition_cv)){
      # drop Cal rows from the inherited knndm folds so caret only sees surviving rows
      keep_mask <- !(seq_len(nrow(Train) + nrow(Cal)) %in% cal_idx)
      new_pos <- cumsum(keep_mask)
      remap_fold <- function(idx_list) lapply(idx_list, function(i){
        i <- i[keep_mask[i]]; unname(new_pos[i])
      })
      partition_cv$indx_train   <- remap_fold(partition_cv$indx_train)
      partition_cv$indx_test    <- remap_fold(partition_cv$indx_test)
      partition_cv$indx_exclude <- remap_fold(partition_cv$indx_exclude)
    }
  }

  Train.sf <- sf::st_as_sf(Train, coords = c('Longitude', 'Latitude'), crs = 32613)
  
  ## remove totally uninformative features using Boruta analysis, these features
  # can only hinder the model, and make prediction onto raster surfaces take longer
  
  BorutaRes <- Boruta::Boruta(Occurrence ~ ., data = Train, num.threads = cores, doTrace = 1)
  importance <- Boruta::attStats(BorutaRes)
  rn <- rownames(importance)
  important_vars <- Boruta::getSelectedAttributes(BorutaRes, withTentative = TRUE)

  # Guard against Boruta rejecting every attribute: Train would collapse to just
  # Occurrence, the mtry grid below becomes 0:0, and ranger errors out. Fall back
  # to the full predictor set so caret has something to tune on.
  if(length(important_vars) == 0){
    warning('Boruta rejected all attributes for ', fname,
            '; keeping all predictors (no feature pruning) for this fit.', immediate. = TRUE)
    important_vars <- setdiff(names(Train), 'Occurrence')
  }

  keep <- unique(c('Occurrence', important_vars))
  Train <- Train[ , names(Train) %in% keep]
  
  # develop a cross validation structure which is explicitly spatial. Under `part` we
  # inherit the folds from Partitioner.R (spatial_mapping or LMPO); otherwise, fall back
  # to a fresh in-training CAST::knndm() draw.
  if(!is.null(partition_cv)){
    indices_knndm <- partition_cv
  } else {
    indices_knndm <- CAST::knndm(Train.sf, rast_dat, k=10)
    indices_knndm$indx_test    <- NULL  # fallback uses caret's default indexOut
    indices_knndm$indx_exclude <- NULL
  }

  # Now we will tune the hyperparameters for this model.
  
  tgrid <- expand.grid(
    mtry = 
      floor(ncol(Train)/ 2.4):floor(ncol(Train)/ 1.6),
    splitrule = 'gini',
    min.node.size = c(1:9, seq(10, 30, by = 5))
  )

  # calculate class weights for the factor levels.
  wts = c(
    1 - sum(Train$Occurrence==0)/nrow(Train),
    1 - sum(Train$Occurrence==1)/nrow(Train)
  )

  # WKDE: inverse env-density case weights on Train (presences only; absences = 1).
  # Computed after Boruta pruning so KDE uses the predictor set the model will see.
  cw <- switch(weight_scheme,
               W0   = rep(1, nrow(Train)),
               WKDE = envPCWeights(Train),
               WMAH = envMahalanobisWeights(Train))

  message('Tuning hyperparameters.')
  model <- caret::train(
    x = Train[,-grep('Occurrence', colnames(Train))],
    y = Train$Occurrence,
    method = "ranger",
    num.trees = 750,
    metric = 'Accuracy',
    tuneGrid = tgrid,
    keep.inbag = TRUE,
    class.weights = wts,
    weights = cw,
    importance = 'permutation',
    trControl = caret::trainControl(
      method="cv",
      index    = indices_knndm$indx_train,
      indexOut = indices_knndm$indx_test,   # NULL under the knndm fallback - caret defaults
      savePredictions = "final",
      allowParallel = TRUE)
  )

  rf_model <- ranger::ranger(
    Occurrence ~ ., data = Train, probability = T, keep.inbag = TRUE,
    mtry = model[['finalModel']][['mtry']],
    min.node.size = model[['finalModel']][['min.node.size']],
    importance = 'permutation',
    class.weights = wts,
    case.weights = cw
    )
  
  # save the cv fold fit model for AOA preds
  saveRDS(model,
          file = paste0(results_root, '/modelsTune/', fname, '.rds'))
  # save the model
  saveRDS(rf_model,
          file = paste0(results_root, '/models/', fname, '.rds'))

  # WKDE: fit Platt on the unweighted calibration fold and save the mapping. Downstream
  # scoring and the raster surface apply platt$apply() to the presence-class probability
  # (column 2 of the ranger prediction matrix); W0 uses the identity.
  platt <- NULL
  if(weight_scheme %in% c('WKDE', 'WMAH') && !is.null(Cal)){
    p_cal <- predict(rf_model, Cal, type = 'response', num.threads = 1)$predictions[, '1']
    platt <- plattCalibrate(Cal$Occurrence, p_cal)
    saveRDS(platt, file = paste0(results_root, '/modelsTune/', fname, '-platt.rds'))
    message(sprintf('Platt coefs: intercept = %.3f, slope = %.3f',
                    platt$coef['intercept'], platt$coef['slope']))
  }
  platt_apply <- if(is.null(platt)) function(p) p else platt$apply

  # save the test data.
  write.csv(Test, paste0(results_root, '/test_data/', fname, '.csv'))


  # threshold the model and use these values for binary classification estimates
  predictions <- predict(rf_model, Test, type = 'se', se.method = 'infjack', probability=TRUE)
  # apply Platt to the presence-class column; raw SE columns are left untouched (WKDE
  # recalibration breaks the infjack SE scale; those surfaces are left as a known limit).
  predictions$predictions[, 2] <- platt_apply(predictions$predictions[, 2])
  predictions$predictions[, 1] <- 1 - predictions$predictions[, 2]
  e <- dismo::evaluate(
    p = predictions$predictions[Test$Occurrence==1,2],
    a = predictions$predictions[Test$Occurrence==0,2]
  )
  
  th <- dismo::threshold(e)
  saveRDS(th, file = paste0(results_root, '/evaluations/', fname, '-thresh.rds'))
  saveRDS(e, file = paste0(results_root, '/evaluations/', fname, '-eval.rds'))
  
  # save the confusion matrix
  predictions <- predict(rf_model, Test, type = 'se', se.method = 'infjack', probability=TRUE)
  predictions$predictions[, 2] <- platt_apply(predictions$predictions[, 2])
  predictions$predictions[, 1] <- 1 - predictions$predictions[, 2]
  predictions$binary <- as.factor(if_else(predictions$predictions[,2] <= th$spec_sens, 0, 1))
  
  cmRestrat <- caret::confusionMatrix(predictions$binary, Test$Occurrence, 
                                      positive = '1', mode = 'everything')
  saveRDS(cmRestrat,
          file = paste0(results_root, '/tables/', fname, '.rds'))
  
  # we will also save the pr-auc, ROC-auc, and Brier score metrics.
  df_auc <- data.frame(
    truth = as.factor(Test$Occurrence),
    Class1 = predictions$predictions[,2]
  )

  pr_auc_val <- yardstick::pr_auc(
    data = df_auc, truth = truth, Class1, event_level = 'second')
  roc_auc_val <- yardstick::roc_auc(
    df_auc, truth, Class1, event_level = 'second')
  # computed directly: yardstick::brier_class() ignores event_level = 'second' for a
  # single binary probability column and scores it as P(absence), inflating Brier.
  brier_val <- data.frame(.metric = 'brier_class', .estimator = 'binary',
    .estimate = mean((as.numeric(as.character(Test$Occurrence)) - predictions$predictions[,2])^2))

  # Cox calibration (intercept/slope of truth ~ logit(prob)) - the only rows carrying
  # a real std_error, so the yardstick-derived rows above get NA for that column.
  cox_val <- coxCalibration(truth = Test$Occurrence, prob = predictions$predictions[,2])

  # Continuous Boyce index (ecospat): Spearman between predicted-suitability bins and
  # presence-vs-expected ratio. Background = test absences (consistent across every
  # fit on disk, no raster re-read needed; a defensible proxy for the full landscape).
  boyce_cor <- tryCatch(
    ecospat::ecospat.boyce(
      fit = predictions$predictions[Test$Occurrence == 0, 2],
      obs = predictions$predictions[Test$Occurrence == 1, 2],
      PEplot = FALSE, rm.duplicate = TRUE)$cor,
    error = function(e){ message('boyce failed: ', conditionMessage(e)); NA_real_ })
  boyce_val <- data.frame(.metric = 'boyce', .estimator = 'continuous',
    .estimate = if(length(boyce_cor) == 1 && is.numeric(boyce_cor)) as.numeric(boyce_cor) else NA_real_)

  setNames(
    data.frame(
      rbind(
        pr_auc_val,
        roc_auc_val,
        brier_val,
        boyce_val
      )
    ), nm = c('metric', 'estimator', 'estimate')
  ) |>
    mutate(std_error = NA_real_) |>
    dplyr::bind_rows(cox_val) |>
    mutate(resolution = resolution, iteration = iteration) |>
    write.csv(paste0(results_root, '/tables/', fname, '.csv'),
              row.names = F)

  # decision curve analysis (net benefit vs. threshold probability) - a separate
  # curve, not a single scalar, so it gets its own file alongside the dismo
  # eval/threshold objects rather than a row in the metrics table above.
  dca <- decisionCurve(truth = Test$Occurrence, prob = predictions$predictions[,2])
  write.csv(dca, paste0(results_root, '/evaluations/', fname, '-dca.csv'), row.names = FALSE)

  rm(df, df_auc, TrainIndex, Train, Test, predictions, cmRestrat, dca, cox_val)
  }

  eval_path <- paste0(results_root, '/tables/', fname, '.csv')
  eval_tab <- if(file.exists(eval_path)) read.csv(eval_path) else NULL

  if(predict_surface){

  pout <- paste0(results_root, '/suitability_maps')
  ###################      PREDICT ONTO SURFACE        ######################### 
  
  if(!file.exists(file.path(pout, paste0(fname, '-Pr.tif')))){
  
    pr <- function(...){
      pp <- predict(..., type = 'response', num.threads = 1)$predictions
      pp[, 2] <- platt_apply(pp[, 2])
      pp[, 1] <- 1 - pp[, 2]
      pp
    }
  
    if(resolution %in% c('3arc', '1arc')){ntile = 1} else 
      if(resolution == '1-3arc'){ntile = 2} else {ntile = 4}  
  
    if(ntile > 1){
    
     tile_path_4pr <- file.path(pout, paste0('tilesPR', '_', resolution))
     if(file.exists(tile_path_4pr)){
       message('Tiles already created for this resolution, skipping to prediction!\n')
     } else {
  
        dir.create(tile_path_4pr, showWarnings = F); message('Making tiles for prediction')
        template <- rast(nrows = ntile, ncols = ntile, extent = ext(rast_dat), crs = crs(rast_dat))
        terra::makeTiles(rast_dat, template, filename = file.path(tile_path_4pr, "tile_.tif"))
        rm(template)
      }
    
     tiles <- file.path(tile_path_4pr, list.files(tile_path_4pr))
     pr_tile_path <- file.path(pout, paste0('pr_tiles', '_', resolution, iteration))
     dir.create(pr_tile_path, showWarnings = F)
    
     message('Writing Predicted Probability to Raster using tiles - this while take some time')
     pb <- txtProgressBar(
       min = 0,  max = length(tiles), style = 3, width = 50, char = "+")
     for (i in seq_along(tiles)){
       
       if(!file.exists(file.path(pr_tile_path, paste0(i, '.tif')))){
       terra::predict(
         rast(tiles[i]), rf_model, f = pr, 
         filename = file.path(pr_tile_path, paste0(i, '.tif')),
          overwrite = T, na.rm=TRUE)
        setTxtProgressBar(pb, i)
        gc(verbose = FALSE)
     }
     close(pb)
    }
    
     mos <- terra::mosaic(sprc(
       file.path(pr_tile_path, list.files(pr_tile_path))
     ), fun = 'mean')
      writeRaster(
        mos[[2]], 
        wopt = list(names = 'Probability'),
       filename = file.path(pout, paste0(fname, '-Pr.tif')))
    
    rm(mos)

    # the Pr.tif mosaic above is now the durable output; these scratch tiles (the split
    # predictor stack, and the per-tile predictions) aren't needed once it exists.
    unlink(tile_path_4pr, recursive = TRUE)
    unlink(pr_tile_path, recursive = TRUE)

    } else { # in these cases, we only need to use a single tile for prediction, we can
     # just use the existing virtual raster to do this. 
    
      if(!file.exists(file.path(pout, paste0(fname, '-Pr.tif')))){
      message('Writing Predicted Probability to Raster')
        terra::predict( # rasters, skip straight to modelling. 
          cores = 1, f = pr, 
          rast_dat, rf_model, cpkgs = "ranger",
          filename = file.path(pout, paste0(resolution, '-IterationCoarse', iteration, '.tif')),
          wopt = list(names = 'predicted_suitability'), na.rm=TRUE,
          overwrite = T)
    
        writeRaster( # we wrote a raster with both predicted class probabilities onto it. 
        # we don't want both, we are going to 'rewrite' the raster so only one class remains. 
          rast(
            file.path(
              pout, paste0(resolution, '-IterationCoarse', iteration, '.tif')))[[2]],
          file.path(pout, paste0(fname, '-Pr.tif')), 
          overwrite = T
      )
      file.remove(
        file.path(
          pout, paste0(resolution, '-IterationCoarse', iteration, '.tif')
          )
        )
      } else {
        'Predicted Probability Raster already exists - skipping.'}
    }
  
  gc(verbose = FALSE)

  }
  
  
  
  ################ AREA OF APPLICABILITY SURFACE    ############################
  if(!exists('rf_model')){
    rf_model <- readRDS(paste0(results_root, '/models/', fname, '.rds'))
  }
  # Skip when the surfaces already exist (matches the Pr-raster guard above). Building them -
  # trainDI + block-wise aoa() + LPD - is expensive, especially at 1/3 arc-second, so don't
  # redo it on every resume/re-run. aoaSurfaces() also self-skips under overwrite = FALSE.
  if(!file.exists(file.path(results_root, 'suitability_maps', paste0(fname, '-AOA-surfaces.tif')))){
    aoaSurfaces(model, rast_dat, fname, results_root)
  }
  
  ###############      STANDARD ERROR PREDICTION        ########################
  # SE predictions are memory-heavy; tile the raster, predict per tile, mosaic.
  # Note the ranger package calls this `se` but it's actually a confidence
  # interval - https://github.com/imbs-hl/ranger/issues/136

  if(se_prediction == TRUE){

  tile_path_4se <- file.path(pout, paste0(resolution, 'TilesSE'))
  final_se_path <- file.path(pout, paste0(resolution, 'SETiles'))

  # tile count tuned so per-tile size stays under ~200MB (empirical safe limit).
  if(resolution == '3arc'){ntile = 2} else
    if(resolution == '1arc'){ntile = 6} else
      if(resolution == '1-3arc'){ntile = 16}
  
  if(resolution == '3m'){
    'Confidence intervals are not produced at this resolution.'}  else {
  
    # don't create the tiles if they already exist.
    if(file.exists(tile_path_4se)){
      message('Tiles for SE exist at this resolution, skipping to predict.')} else {
     
        message('Making tiles for prediction of standard errors')
        dir.create(tile_path_4se, showWarnings = F)
        dir.create(final_se_path, showWarnings = F)
      
        template <- rast(nrows = ntile, ncols = ntile, extent = ext(rast_dat), crs = crs(rast_dat))
        terra::makeTiles(rast_dat, template, filename = file.path(tile_path_4se, "tile_.tif"))
        rm(template)
    }
  
    tiles <- file.path(tile_path_4se, list.files(tile_path_4se))
    se <- function(...) predict(..., type = 'se', se.method = 'infjack',
                               predict.all = FALSE,
                                probability = TRUE, num.threads = cores/4)$se
  
    # # predict the standard error onto the tiles.
    # create and initialize progress bar
    message('Predicting SE to tiles; this may take a really long time')
    pb <- txtProgressBar( 
      min = 0,  max = length(tiles), style = 3, width = 50, char = "+")
  
    for (i in seq_along(tiles)){
      if(!file.exists(file.path(final_se_path, paste0('SE', i, '.tif')))){ # in case of crash, pick up where left off. 
      terra::predict(
        rast(tiles[i]), rf_model, f = se, 
        filename = file.path(final_se_path, paste0('SE', i, '.tif')),
        overwrite = T, na.rm=TRUE)
      gc(verbose = FALSE)}
      setTxtProgressBar(pb, i)
    }
    close(pb)
  
    mos <- terra::mosaic(sprc(
      file.path(final_se_path, list.files(final_se_path))
    ), fun = 'mean')
    writeRaster(
      mos[[2]],
      wopt = list(names = 'standardError'),
      filename = file.path(pout, paste0(fname, '-SE.tif')),
      overwrite = T)
    gc(verbose = FALSE)
    }
    unlink(final_se_path, recursive = TRUE)
    unlink(tile_path_4se, recursive = TRUE)
  }
  }

  invisible(list(fname = fname, metrics = eval_tab))
}


